{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Prucalopride, a structurally related 5-HT4 benzamide sharing the 4-amino-5-chloro-2-methoxybenzamide pharmacophore, has an absolute oral bioavailability greater than 90% in humans, strongly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Metoclopramide, which shares the same substituted benzamide core, has a mean oral bioavailability of 76% (range 64-97%) in normal volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Amisulpride, a substituted benzamide with a basic amine side chain, has an absolute bioavailability of approximately 50%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Melperone, a piperidine-containing drug with a 4-fluorophenyl moiety, has an absolute bioavailability of 64 ± 16.6% in healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Sulpiride, a related benzamide, has an oral bioavailability of about 30%, which is still above the 20% threshold and supports high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 4-amino-5-chloro-2-methoxybenzamide 5-HT4 agonist closely related to prucalopride and metoclopramide, both of which have high oral bioavailability. Other benzamide and piperidine analogues (amisulpride, sulpiride, melperone) also show F ≥ 27-50%. The only low-bioavailability analogue, lumateperone (4.4%), is structurally distant and not transferable. Therefore, F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the query molecule.",
    "The effects of the 4-fluorophenoxypropyl and piperidine methoxy substituents on metabolism, efflux, or solubility are not directly measured.",
    "Formulation-dependent absorption variability is not accounted for in the extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

